localparam 
// | ----------- address 32 ----------- |
// | tag 23 | index 5 | word 2 | byte 2 |
    ADDR_BITS = 32,
    WORD_BYTES = 4,
    WORD_BYTES_WIDTH = 2,   // log2(4 (WORD_BYTES))
    WORD_BITS = (WORD_BYTES * 8),
    ELEMENT_WORDS = 4,
    ELEMENT_WORDS_WIDTH = 2,   // log2(4 (ELEMENT_WORDS))
    BLOCK_WIDTH = (ELEMENT_WORDS_WIDTH + WORD_BYTES_WIDTH),   // 4
    ELEMENT_NUM = 64,
    WAYS = 2,
    ELEMENT_INDEX_WIDTH = 6,   // log2(64)
    SET_INDEX_WIDTH = 5,   // log2(64 / 2 (WAYS))
    TAG_BITS = (ADDR_BITS - SET_INDEX_WIDTH - BLOCK_WIDTH);  // 32 - 5 - 4 = 23
    =====CACHE=====
     1	// | ----------- address 32 ----------- |
     2	// | 31   9 | 8     4 | 3    2 | 1    0 |
     3	// | tag 23 | index 5 | word 2 | byte 2 |
     4	
     5	module cache (
     6		input wire clk,  // clock
     7		input wire rst,  // reset
     8		input wire [ADDR_BITS-1:0] addr,  // address
     9	    input wire load,    //  read refreshes recent bit
    10		input wire store,  // set valid to 1 and reset dirty to 0
    11		input wire edit,  // set dirty to 1
    12		input wire invalid,  // reset valid to 0
    13	    input wire [2:0] u_b_h_w, // select signed or not & data width
    14	                              // please refer to definition of LB, LH, LW, LBU, LHU in RV32I Instruction Set  
    15		input wire [31:0] din,  // data write in
    16		output reg hit = 0,  // hit or not
    17		output reg [31:0] dout = 0,  // data read out
    18		output reg valid = 0,  // valid bit
    19		output reg dirty = 0,  // dirty bit
    20		output reg [TAG_BITS-1:0] tag = 0  // tag bits
    21		);
    22	
    23	    `include "addr_define.vh"
    24	
    25	    wire [31:0] word1, word2;
    26	    wire [15:0] half_word1, half_word2;
    27	    wire [7:0]  byte1, byte2;
    28	    wire recent1, recent2, valid1, valid2, dirty1, dirty2;
    29	    wire [TAG_BITS-1:0] tag1, tag2;
    30	    wire hit1, hit2;
    31	
    32	    reg [ELEMENT_NUM-1:0] inner_recent = 0; // for LRU
    33	    reg [ELEMENT_NUM-1:0] inner_valid = 0;
    34	    reg [ELEMENT_NUM-1:0] inner_dirty = 0;
    35	    reg [TAG_BITS-1:0] inner_tag [0:ELEMENT_NUM-1];
    36	    // 64 elements, 2 ways set associative => 32 sets
    37	    reg [31:0] inner_data [0:ELEMENT_NUM*ELEMENT_WORDS-1];
    38	
    39	    // initialize tag and data with 0
    40	    integer i;
    41	    initial begin
    42	        for (i = 0; i < ELEMENT_NUM; i = i + 1)
    43	            inner_tag[i] = 23'b0;
    44	
    45	        for (i = 0; i < ELEMENT_NUM*ELEMENT_WORDS; i = i + 1)
    46	            inner_data[i] = 32'b0;
    47	    end
    48	
    49	    // the bits in an input address:
    50	    wire [TAG_BITS-1:0] addr_tag;
    51	    wire [SET_INDEX_WIDTH-1:0] addr_index;     // idx of set
    52	    wire [ELEMENT_INDEX_WIDTH-1:0] addr_element1; 
    53	    wire [ELEMENT_INDEX_WIDTH-1:0] addr_element2;     // idx of element
    54	    wire [ELEMENT_INDEX_WIDTH+ELEMENT_WORDS_WIDTH-1:0] addr_word1;
    55	    wire [ELEMENT_INDEX_WIDTH+ELEMENT_WORDS_WIDTH-1:0] addr_word2; // element index + word index
    56	
    57	    assign addr_tag = addr[ADDR_BITS-1 : ADDR_BITS-TAG_BITS];             // addr[31:9]
    58	    assign addr_index = addr[ADDR_BITS-TAG_BITS-1 : BLOCK_WIDTH];         // addr[8:4]
    59	    assign addr_element1 = {addr_index, 1'b0};
    60	    assign addr_element2 = {addr_index, 1'b1};      // way 2 的 element 下标
    61	    assign addr_word1 = {addr_element1, addr[ELEMENT_WORDS_WIDTH+WORD_BYTES_WIDTH-1:WORD_BYTES_WIDTH]};
    62	    assign addr_word2 = {addr_element2, addr[ELEMENT_WORDS_WIDTH+WORD_BYTES_WIDTH-1:WORD_BYTES_WIDTH]};
    63	
    64	    assign word1 = inner_data[addr_word1];
    65	    assign word2 = inner_data[addr_word2];
    66	    assign half_word1 = addr[1] ? word1[31:16] : word1[15:0];
    67	    assign half_word2 = addr[1] ? word2[31:16] : word2[15:0];
    68	    assign byte1 = addr[1] ?
    69	                    addr[0] ? word1[31:24] : word1[23:16] :
    70	                    addr[0] ? word1[15:8] :  word1[7:0]   ;
    71	    assign byte2 = addr[1] ?
    72	                    addr[0] ? word2[31:24] : word2[23:16] :
    73	                    addr[0] ? word2[15:8] :  word2[7:0]   ;
    74	
    75	    assign recent1 = inner_recent[addr_element1];
    76	    assign recent2 = inner_recent[addr_element2];
    77	    assign valid1 = inner_valid[addr_element1];
    78	    assign valid2 = inner_valid[addr_element2];
    79	    assign dirty1 = inner_dirty[addr_element1];
    80	    assign dirty2 = inner_dirty[addr_element2];
    81	    assign tag1 = inner_tag[addr_element1];
    82	    assign tag2 = inner_tag[addr_element2];
    83	
    84	    assign hit1 = valid1 & (tag1 == addr_tag);
    85	    assign hit2 = valid2 & (tag2 == addr_tag);
    86	
    87	    always @ (posedge clk) begin
    88	        // valid / dirty / tag 输出的是"将要被替换的那一路"(牺牲路)的信息，
    89	        // 与下面 store 时 `if (recent1) 替换 way2 else 替换 way1` 保持一致，
    90	        // cmu 依靠它们判断是否需要写回以及写回到哪个 tag。
    91	        valid <= recent1 ? valid2 : valid1;                  // 牺牲路的 valid
    92	        dirty <= recent1 ? dirty2 : dirty1;                  // 牺牲路的 dirty
    93	        tag <= recent1 ? tag2 : tag1;                        // 牺牲路的 tag
    94	        hit <= hit1 | hit2;                                  // 任一路命中即命中
    95	
    96	        // read $ with load==0 means moving data from $ to mem
    97	        // no need to update recent bit
    98	        // otherwise the refresh process will be affected
    99	        if (load) begin
   100	            if (hit1) begin
   101	                dout <=
   102	                    u_b_h_w[1] ? word1 :
   103	                    u_b_h_w[0] ? {u_b_h_w[2] ? 16'b0 : {16{half_word1[15]}}, half_word1} :
   104	                    {u_b_h_w[2] ? 24'b0 : {24{byte1[7]}}, byte1};
   105	                
   106	                // inner_recent will be refreshed only on r/w hit
   107	                // (including the r/w hit after miss and replacement)
   108	                inner_recent[addr_element1] <= 1'b1;
   109	                inner_recent[addr_element2] <= 1'b0;
   110	            end
   111	            else if (hit2) begin
   112	                    // way 2 命中，逻辑与 way 1 完全对称
   113	                    dout <=
   114	                        u_b_h_w[1] ? word2 :
   115	                        u_b_h_w[0] ? {u_b_h_w[2] ? 16'b0 : {16{half_word2[15]}}, half_word2} :
   116	                        {u_b_h_w[2] ? 24'b0 : {24{byte2[7]}}, byte2};
   117	
   118	                    inner_recent[addr_element1] <= 1'b0;
   119	                    inner_recent[addr_element2] <= 1'b1;
   120	            end
   121	        end
   122	        else dout <= inner_data[ recent1 ? addr_word2 : addr_word1 ];
   123	
   124	        if (edit) begin
   125	            if (hit1) begin
   126	                inner_data[addr_word1] <= 
   127	                    u_b_h_w[1] ?        // word?
   128	                        din
   129	                    :
   130	                        u_b_h_w[0] ?    // half word?
   131	                            addr[1] ?       // upper / lower?
   132	                                {din[15:0], word1[15:0]} 
   133	                            :
   134	                                {word1[31:16], din[15:0]} 
   135	                        :   // byte
   136	                            addr[1] ?
   137	                                addr[0] ?
   138	                                    {din[7:0], word1[23:0]}   // 11
   139	                                :
   140	                                    {word1[31:24], din[7:0], word1[15:0]} // 10
   141	                            :
   142	                                addr[0] ?
   143	                                    {word1[31:16], din[7:0], word1[7:0]}   // 01
   144	                                :
   145	                                    {word1[31:8], din[7:0]} // 00
   146	                ;
   147	                inner_dirty[addr_element1] <= 1'b1;
   148	                inner_recent[addr_element1] <= 1'b1;
   149	                inner_recent[addr_element2] <= 1'b0;
   150	            end
   151	            else if (hit2) begin
   152	                    // way 2 命中，写入逻辑与 way 1 完全对称
   153	                    inner_data[addr_word2] <=
   154	                        u_b_h_w[1] ?        // word?
   155	                            din
   156	                        :
   157	                            u_b_h_w[0] ?    // half word?
   158	                                addr[1] ?       // upper / lower?
   159	                                    {din[15:0], word2[15:0]}
   160	                                :
   161	                                    {word2[31:16], din[15:0]}
   162	                            :   // byte
   163	                                addr[1] ?
   164	                                    addr[0] ?
   165	                                        {din[7:0], word2[23:0]}   // 11
   166	                                    :
   167	                                        {word2[31:24], din[7:0], word2[15:0]} // 10
   168	                                :
   169	                                    addr[0] ?
   170	                                        {word2[31:16], din[7:0], word2[7:0]}   // 01
   171	                                    :
   172	                                        {word2[31:8], din[7:0]} // 00
   173	                    ;
   174	                    inner_dirty[addr_element2] <= 1'b1;
   175	                    inner_recent[addr_element1] <= 1'b0;
   176	                    inner_recent[addr_element2] <= 1'b1;
   177	            end
   178	        end
   179	
   180	        if (store) begin
   181	            if (recent1) begin  // replace 2
   182	                inner_data[addr_word2] <= din;
   183	                inner_valid[addr_element2] <= 1'b1;
   184	                inner_dirty[addr_element2] <= 1'b0;
   185	                inner_tag[addr_element2] <= addr_tag;
   186	            end else begin
   187	                // recent2 == 1 => replace 1
   188	                // recent2 == 0 => no data in this set, place to 1
   189	                inner_data[addr_word1] <= din;
   190	                inner_valid[addr_element1] <= 1'b1;
   191	                inner_dirty[addr_element1] <= 1'b0;
   192	                inner_tag[addr_element1] <= addr_tag;
   193	            end
   194	        end
   195	
   196	        // not used currently, can be used to reset the cache.
   197	        if (invalid) begin
   198	            inner_recent[addr_element1] <= 1'b0;
   199	            inner_recent[addr_element2] <= 1'b0;
   200	            inner_valid[addr_element1] <= 1'b0;
   201	            inner_valid[addr_element2] <= 1'b0;
   202	            inner_dirty[addr_element1] <= 1'b0;
   203	            inner_dirty[addr_element2] <= 1'b0;
   204	        end
   205	    end
   206	
   207	endmodule

     1	module cmu (
     2	        // CPU side
     3			input clk,
     4			input rst,
     5			input [31:0] addr_rw,
     6			input en_r,
     7			input en_w,
     8	        input [2:0] u_b_h_w,
     9			input [31:0] data_w,
    10			output [31:0] data_r,
    11			output stall,
    12	
    13	        // mem side
    14			output reg mem_cs_o = 0,
    15			output reg mem_we_o = 0,
    16			output reg [31:0] mem_addr_o = 0,
    17			input [31:0] mem_data_i,
    18			output [31:0] mem_data_o,
    19			input mem_ack_i,
    20	
    21	        // debug info
    22	        output [2:0] cmu_state
    23		);
    24	
    25	    `include "addr_define.vh"
    26	
    27	    reg [ADDR_BITS-1:0] cache_addr = 0;
    28	    reg cache_load = 0;
    29	    reg cache_store = 0;
    30	    reg cache_edit = 0;
    31	    reg [2:0] cache_u_b_h_w = 0;
    32	    reg [WORD_BITS-1:0] cache_din = 0;
    33	    wire cache_hit;
    34	    wire [WORD_BITS-1:0] cache_dout;
    35	    wire cache_valid;
    36	    wire cache_dirty;
    37	    wire [TAG_BITS-1:0] cache_tag;
    38	
    39	    cache CACHE (
    40	        .clk(~clk),
    41	        .rst(rst),
    42	        .addr(cache_addr),
    43	        .load(cache_load),
    44	        .store(cache_store),
    45	        .edit(cache_edit),
    46	        .invalid(1'b0),
    47	        .u_b_h_w(cache_u_b_h_w),
    48	        .din(cache_din),
    49	        .hit(cache_hit),
    50	        .dout(cache_dout),
    51	        .valid(cache_valid),
    52	        .dirty(cache_dirty),
    53	        .tag(cache_tag)
    54	    );
    55	
    56	    localparam
    57	        S_IDLE = 0,
    58	        S_PRE_BACK = 1,
    59	        S_BACK = 2,
    60	        S_FILL = 3,
    61	        S_WAIT = 4;
    62	
    63	    reg [2:0]state = 0;
    64	    reg [2:0]next_state = 0;
    65	    reg [ELEMENT_WORDS_WIDTH-1:0]word_count = 0;
    66	    reg [ELEMENT_WORDS_WIDTH-1:0]next_word_count = 0;
    67	    assign cmu_state = state;
    68	
    69	    always @ (posedge clk) begin
    70	        if (rst) begin
    71	            state <= S_IDLE;
    72	            word_count <= 2'b00;
    73	        end
    74	        else begin
    75	            state <= next_state;
    76	            word_count <= next_word_count;
    77	        end
    78	    end
    79	
    80	    // state ctrl
    81	    always @ (*) begin
    82	        if (rst) begin
    83	            next_state = S_IDLE;
    84	            next_word_count = 2'b00;
    85	        end
    86	        else begin
    87	            case (state)
    88	                S_IDLE: begin
    89	                    if (en_r || en_w) begin
    90	                        if (cache_hit)
    91	                            next_state = S_IDLE;        // 命中，一个周期完成
    92	                        else if (cache_valid && cache_dirty)
    93	                            next_state = S_PRE_BACK;    // 缺失且牺牲行为脏，先写回
    94	                        else
    95	                            next_state = S_FILL;        // 缺失但牺牲行干净，直接填充
    96	                    end
    97	                    next_word_count = 2'b00;
    98	                end
    99	
   100	                S_PRE_BACK: begin
   101	                    next_state = S_BACK;
   102	                    next_word_count = 2'b00;
   103	                end
   104	
   105	                S_BACK: begin
   106	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})    // 2'b11 in default case
   107	                        next_state = S_FILL;            // 整块写回完成，转入填充
   108	                    else
   109	                        next_state = S_BACK;
   110	
   111	                    if (mem_ack_i)
   112	                        next_word_count = word_count + 1'b1;
   113	                    else
   114	                        next_word_count = word_count;
   115	                end
   116	
   117	                S_FILL: begin
   118	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})
   119	                        next_state = S_WAIT;            // 整块填充完成，补做本次访问
   120	                    else
   121	                        next_state = S_FILL;
   122	
   123	                    if (mem_ack_i)
   124	                        next_word_count = word_count + 1'b1;
   125	                    else
   126	                        next_word_count = word_count;
   127	                end
   128	
   129	                S_WAIT: begin
   130	                    next_state = S_IDLE;
   131	                    next_word_count = 2'b00;
   132	                end
   133	            endcase
   134	        end
   135	    end
   136	    
   137	    // cache ctrl
   138	    always @ (*) begin
   139	        case(state)
   140	            S_IDLE, S_WAIT: begin
   141	                cache_addr = addr_rw;
   142	                cache_load = en_r;
   143	                cache_edit = en_w;
   144	                cache_store = 1'b0;
   145	                cache_u_b_h_w = u_b_h_w;
   146	                cache_din = data_w;
   147	            end
   148	            S_BACK, S_PRE_BACK: begin
   149	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   150	                cache_load = 1'b0;
   151	                cache_edit = 1'b0;
   152	                cache_store = 1'b0;
   153	                cache_u_b_h_w = 3'b010;
   154	                cache_din = 32'b0;
   155	            end
   156	            S_FILL: begin
   157	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   158	                cache_load = 1'b0;
   159	                cache_edit = 1'b0;
   160	                cache_store = mem_ack_i;
   161	                cache_u_b_h_w = 3'b010;
   162	                cache_din = mem_data_i;
   163	            end
   164	        endcase
   165	    end
   166	    assign data_r = cache_dout;
   167	
   168	    // mem ctrl
   169	    always @ (*) begin
   170	        case (next_state)
   171	            S_IDLE, S_PRE_BACK, S_WAIT: begin
   172	                mem_cs_o = 1'b0;
   173	                mem_we_o = 1'b0;
   174	                mem_addr_o = 32'b0;
   175	            end
   176	
   177	            S_BACK: begin
   178	                mem_cs_o = 1'b1;
   179	                mem_we_o = 1'b1;
   180	                mem_addr_o = {cache_tag, addr_rw[ADDR_BITS-TAG_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   181	            end
   182	
   183	            S_FILL: begin
   184	                mem_cs_o = 1'b1;
   185	                mem_we_o = 1'b0;
   186	                mem_addr_o = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   187	            end
   188	        endcase
   189	    end
   190	    assign mem_data_o = cache_dout;
   191	
   192	    // 只有在 S_IDLE(直接命中) 或 S_WAIT(缺失处理完毕后补做访问) 且 cache 命中时，
   193	    // 本次访存才算完成，其余情况都要让流水线暂停。
   194	    // 注意：S_FILL 期间 cache_hit 也可能被置起(tag 已写入)，所以必须用状态限定。
   195	    assign stall = (en_r | en_w) & ~(cache_hit & ((state == S_IDLE) | (state == S_WAIT)));
   196	
   197	endmodule
=====DATARAM=====
     1	module data_ram (
     2		input wire clk,
     3		input wire rst,
     4		input wire cs,
     5		input wire we,
     6		input wire [31:0] addr,
     7		input wire [31:0] din,
     8		output wire [31:0] dout,
     9		output wire stall,
    10		output reg ack = 0,
    11		output [2:0] ram_state
    12		);
    13		
    14		parameter
    15			ADDR_WIDTH = 11;
    16	
    17		localparam
    18			S_IDLE = 0,
    19			S_READING1 = 1,
    20			S_READING2 = 2,
    21			S_READ = 3,
    22			S_WRITING1 = 4,
    23			S_WRITING2 = 5,
    24			S_WRITE = 6;
    25		
    26		reg [31:0] data [0:(1<<ADDR_WIDTH)-1];
    27		
    28		integer i = 0;
    29		initial	begin
    30			for (i = 12; i < (1<<ADDR_WIDTH); i = i + 1) begin
    31				data[i] <= 32'b0;
    32			end
    33			$readmemh("ram.mem", data);
    34		end
    35	
    36		reg [2:0]state = 0;
    37		reg [31:0] out = 0;
    38		assign ram_state = state;
    39	
    40		reg [2:0]next_state = 0;
    41	
    42		always @ (posedge clk) begin
    43			if (rst) begin
    44				state = 0;
    45			end
    46			else begin
    47				state <= next_state;
    48			end
    49		end
    50	
    51		always @ (*) begin
    52			if (cs) begin
    53				if (we) begin
    54					if(state == S_IDLE)
    55						next_state = S_WRITING1;
    56					else if (S_WRITING1 <= state && state <= S_WRITING2)
    57						next_state = state + 1;
    58					else if (state == S_WRITE)
    59						next_state = S_IDLE;
    60					else
    61						next_state = 3'bxxx;
    62				end
    63				else begin
    64					if (S_IDLE <= state && state <= S_READING2)
    65						next_state = state + 1;
    66					else if (state == S_READ)
    67						next_state = S_IDLE;
    68					else
    69						next_state = 3'bxxx;
    70				end
    71			end
    72			else begin
    73				next_state = S_IDLE;
    74			end
    75		end
    76	
    77		always @ (posedge clk) begin
    78			if (state != S_READ && state != S_WRITE) begin
    79				ack <= 0;
    80				out <= 0;
    81			end
    82	
    83			else if (state == S_READ) begin
    84				ack <= 1;
    85				out <= data[addr[ADDR_WIDTH+1:2]];
    86			end
    87	
    88			else if (state == S_WRITE) begin
    89				ack <= 1;
    90				data[addr[ADDR_WIDTH+1:2]] <= din;
    91			end
    92	
    93			else begin
    94				ack <= 0;
    95				out <= 0;
    96			end
    97		end
    98	
    99	
   100		// always @ (posedge clk or posedge rst) begin
   101		// 	if (rst) begin
   102		// 		state <= S_IDLE;
   103		// 		ack <= 0;
   104		// 		out <= 0;
   105		// 	end else begin
   106		// 		if (cs) begin
   107		// 			if (we) begin // write
   108		// 				out <= 0;
   109		// 				if (state == S_IDLE) begin
   110		// 					state <= S_WRITING1;
