 34	    // 实现：冒险检测与前递控制
 35	    initial begin
 36	        hazard_optype_EXE = 2'd0;
 37	        hazard_optype_MEM = 2'd0;
 38	    end
 39	
 40	    // ID 级真正需要读寄存器（x0 不算）
 41	    wire rs1_valid = rs1use_ID & (rs1_ID != 5'd0);
 42	    wire rs2_valid = rs2use_ID & (rs2_ID != 5'd0);
 43	
 44	    // EXE / MEM 级指令是否会写回寄存器
 45	    wire EXE_write = (hazard_optype_EXE == hazard_optype_ALU) |
 46	                     (hazard_optype_EXE == hazard_optype_LOAD);
 47	    wire MEM_write = (hazard_optype_MEM == hazard_optype_ALU) |
 48	                     (hazard_optype_MEM == hazard_optype_LOAD);
 49	
 50	    wire EXE_is_load = hazard_optype_EXE == hazard_optype_LOAD;
 51	    wire MEM_is_load = hazard_optype_MEM == hazard_optype_LOAD;
 52	
 53	    // 相关判断
 54	    wire rs1_forward_EXE = rs1_valid & EXE_write & (rs1_ID == rd_EXE);
 55	    wire rs2_forward_EXE = rs2_valid & EXE_write & (rs2_ID == rd_EXE);
 56	    wire rs1_forward_MEM = rs1_valid & MEM_write & (rs1_ID == rd_MEM);
 57	    wire rs2_forward_MEM = rs2_valid & MEM_write & (rs2_ID == rd_MEM);
 58	
 59	    // load-use 冒险：EXE 级是 load，ID 级需要它的结果 -> 必须暂停一拍。
 60	    // 例外：ID 级是 store 且只有 rs2（待写入的数据）相关时，可以留到 EXE/MEM
 61	    //       级用 load-store 前递解决，不需要暂停。
 62	    wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;
 63	    wire load_stall = EXE_is_load &
 64	                      (rs1_forward_EXE | (rs2_forward_EXE & ~ID_is_store));
 65	
 66	    // cmu_stall 时整条流水线冻结（PC 与所有流水寄存器都不使能），
 67	    // 访存操作不会被重复发起。
 68	    assign PC_EN_IF = ~cmu_stall & ~load_stall;
 69	    assign reg_FD_stall = load_stall;
 70	    assign reg_FD_flush = Branch_ID & ~load_stall;   // 跳转发生时清除已取的下一条指令
 71	    assign reg_DE_flush = load_stall;                // 向 EXE 级插入气泡
 72	
 73	    // 前递选择：00 = 寄存器堆, 01 = EXE 级 ALU 结果,
 74	    //           10 = MEM 级 ALU 结果, 11 = MEM 级 load 数据
 75	    assign forward_ctrl_A = rs1_forward_EXE ? 2'b01 :
 76	                            rs1_forward_MEM ? (MEM_is_load ? 2'b11 : 2'b10) :
 77	                            2'b00;
 78	    assign forward_ctrl_B = rs2_forward_EXE ? 2'b01 :
 79	                            rs2_forward_MEM ? (MEM_is_load ? 2'b11 : 2'b10) :
 80	                            2'b00;
 81	
 82	    // load-store 前递：EXE 级 store 要写的数据来自 MEM 级 load 的结果
 83	    assign forward_ctrl_ls = (hazard_optype_EXE == hazard_optype_STORE) &
 84	                             MEM_is_load & (rs2_EXE != 5'd0) & (rs2_EXE == rd_MEM);
 85	
 86	endmodule`timescale 1ns / 1ps
