108					input rst,
109					input [4:0] R_addr_A, 
110					input [4:0] R_addr_B, 
111					input [4:0] Wt_addr, 
112					input [31:0]Wt_data, 
113					input L_S, 
114					output [31:0] rdata_A, 
115					output [31:0] rdata_B,
116					input [4:0] Debug_addr,         // debug address
117					output[31:0] Debug_regs        // debug data
118				  );
