120	reg [31:0] register [1:31]; 				// r1 - r31
121	integer i;
122	
123	    // 实现：两读一写的寄存器堆，x0 恒为 0
124		assign rdata_A = (R_addr_A == 5'b0) ? 32'b0 : register[R_addr_A];	// read
125		assign rdata_B = (R_addr_B == 5'b0) ? 32'b0 : register[R_addr_B];	// read
