127	    // 实现：写口在时钟下降沿动作，使 WB 写入的值同周期就能被 ID 级读到
128		always @(negedge clk )         //or posedge rst
129	      begin
130			if (rst==1) 	 begin 			// reset
131			    for (i=1; i<32; i=i+1)
132			    register[i] <= 0;	//i;
133			end
134			else if ((Wt_addr != 5'b0) && (L_S == 1'b1))	// write
135			    register[Wt_addr] <= Wt_data;
136		end
137	    	
138	    assign Debug_regs = (Debug_addr == 0) ? 0 : register[Debug_addr];               //TEST
