145	module ImmGen(
146	            input  wire [2:0] ImmSel,
147	            input  wire [31:0] inst_field,
148	            output[31:0] Imm_out
149	    );
150	    parameter Imm_type_I = 3'b001;
151	    parameter Imm_type_B = 3'b010;
152	    parameter Imm_type_J = 3'b011;
153	    parameter Imm_type_S = 3'b100;
154	    parameter Imm_type_U = 3'b101;
155	
156	    wire I = ImmSel == Imm_type_I;
157	    wire B = ImmSel == Imm_type_B;
158	    wire J = ImmSel == Imm_type_J;
159	    wire S = ImmSel == Imm_type_S;
160	    wire U = ImmSel == Imm_type_U;
161	
162	    // 实现：按 RISC-V 编码规则生成符号扩展后的立即数
163	    wire[31:0] Imm_I = {{20{inst_field[31]}}, inst_field[31:20]};
164	    wire[31:0] Imm_B = {{20{inst_field[31]}}, inst_field[7], inst_field[30:25], inst_field[11:8], 1'b0};
165	    wire[31:0] Imm_J = {{12{inst_field[31]}}, inst_field[19:12], inst_field[20], inst_field[30:21], 1'b0};
166	    wire[31:0] Imm_S = {{20{inst_field[31]}}, inst_field[31:25], inst_field[11:7]};
167	    wire[31:0] Imm_U = {inst_field[31:12], 12'b0};
168	
169	    assign Imm_out = {32{I}} & Imm_I |
170	                     {32{B}} & Imm_B |
171	                     {32{J}} & Imm_J |
172	                     {32{S}} & Imm_S |
173	                     {32{U}} & Imm_U ;
