178	module CtrlUnit(
179	    input[31:0] inst,
180	    input cmp_res,
181	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
182	        MIO, rs1use, rs2use,
183	    output [1:0] hazard_optype,
184	    output [2:0] ImmSel, cmp_ctrl,
185	    output [3:0] ALUControl,
186	    output JALR
187	);
188	
189	    wire[6:0] funct7 = inst[31:25];
190	    wire[2:0] funct3 = inst[14:12];
191	    wire[6:0] opcode = inst[6:0];
192	
193	    wire Rop = opcode == 7'b0110011;
194	    wire Iop = opcode == 7'b0010011;
195	    wire Bop = opcode == 7'b1100011;
196	    wire Lop = opcode == 7'b0000011;
197	    wire Sop = opcode == 7'b0100011;
198	
199	    wire funct7_0  = funct7 == 7'h0;
200	    wire funct7_32 = funct7 == 7'h20;
201	
202	    wire funct3_0 = funct3 == 3'h0;
203	    wire funct3_1 = funct3 == 3'h1;
204	    wire funct3_2 = funct3 == 3'h2;
205	    wire funct3_3 = funct3 == 3'h3;
206	    wire funct3_4 = funct3 == 3'h4;
207	    wire funct3_5 = funct3 == 3'h5;
208	    wire funct3_6 = funct3 == 3'h6;
209	    wire funct3_7 = funct3 == 3'h7;
210	
211	    wire ADD  = Rop & funct3_0 & funct7_0;
212	    wire SUB  = Rop & funct3_0 & funct7_32;
213	    wire SLL  = Rop & funct3_1 & funct7_0;
214	    wire SLT  = Rop & funct3_2 & funct7_0;
215	    wire SLTU = Rop & funct3_3 & funct7_0;
216	    wire XOR  = Rop & funct3_4 & funct7_0;
217	    wire SRL  = Rop & funct3_5 & funct7_0;
218	    wire SRA  = Rop & funct3_5 & funct7_32;
219	    wire OR   = Rop & funct3_6 & funct7_0;
220	    wire AND  = Rop & funct3_7 & funct7_0;
221	
222	    wire ADDI  = Iop & funct3_0;	
223	    wire SLTI  = Iop & funct3_2;
224	    wire SLTIU = Iop & funct3_3;
225	    wire XORI  = Iop & funct3_4;
226	    wire ORI   = Iop & funct3_6;
227	    wire ANDI  = Iop & funct3_7;
228	    wire SLLI  = Iop & funct3_1 & funct7_0;
229	    wire SRLI  = Iop & funct3_5 & funct7_0;
230	    wire SRAI  = Iop & funct3_5 & funct7_32;
231	
232	    wire BEQ = Bop & funct3_0;
233	    wire BNE = Bop & funct3_1;
234	    wire BLT = Bop & funct3_4;
235	    wire BGE = Bop & funct3_5;
236	    wire BLTU = Bop & funct3_6;
237	    wire BGEU = Bop & funct3_7;
238	
239	    wire LB =  Lop & funct3_0;
240	    wire LH =  Lop & funct3_1;
241	    wire LW =  Lop & funct3_2;
242	    wire LBU = Lop & funct3_4;
243	    wire LHU = Lop & funct3_5;
244	
245	    wire SB = Sop & funct3_0;
246	    wire SH = Sop & funct3_1;
247	    wire SW = Sop & funct3_2;
248	
249	    wire LUI   = opcode == 7'b0110111;
250	    wire AUIPC = opcode == 7'b0010111;
251	
252	    wire JAL  =  opcode == 7'b1101111;
253	    assign JALR = (opcode == 7'b1100111) && funct3_0;
254	
255	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
256	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
257	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
258	    wire L_valid = LW | LH | LB | LHU | LBU;
259	    wire S_valid = SW | SH | SB;
260	
261	    parameter Imm_type_I = 3'b001;
262	    parameter Imm_type_B = 3'b010;
263	    parameter Imm_type_J = 3'b011;
264	    parameter Imm_type_S = 3'b100;
265	    parameter Imm_type_U = 3'b101;
266	
267	    parameter cmp_EQ  = 3'b001;
268	    parameter cmp_NE  = 3'b010;
269	    parameter cmp_LT  = 3'b011;
270	    parameter cmp_LTU = 3'b100;
271	    parameter cmp_GE  = 3'b101;
272	    parameter cmp_GEU = 3'b110;
273	
274	    parameter ALU_ADD  = 4'b0001;
275	    parameter ALU_SUB  = 4'b0010;
276	    parameter ALU_AND  = 4'b0011;
277	    parameter ALU_OR   = 4'b0100;
278	    parameter ALU_XOR  = 4'b0101;
279	    parameter ALU_SLL  = 4'b0110;
280	    parameter ALU_SRL  = 4'b0111;
281	    parameter ALU_SLT  = 4'b1000;
282	    parameter ALU_SLTU = 4'b1001;
283	    parameter ALU_SRA  = 4'b1010;
284	    parameter ALU_Ap4  = 4'b1011;
285	    parameter ALU_Bout = 4'b1100;
286	
287	    parameter hazard_optype_ALU = 2'd1;
288	    parameter hazard_optype_LOAD = 2'd2;
289	    parameter hazard_optype_STORE = 2'd3;
290	
291	    // 实现：条件分支成立或无条件跳转时置位 Branch（分支在 ID 级解析）
292	    assign Branch = B_valid & cmp_res | JAL | JALR;
293	
294	    // 实现：根据指令类型选择立即数格式
295	    assign ImmSel = {3{I_valid | L_valid | JALR}} & Imm_type_I |
296	                    {3{B_valid}}                 & Imm_type_B |
297	                    {3{JAL}}                     & Imm_type_J |
298	                    {3{S_valid}}                 & Imm_type_S |
299	                    {3{LUI | AUIPC}}             & Imm_type_U ;
300	
301	    // 实现：根据分支子类型选择 cmp_32 的比较方式
302	    assign cmp_ctrl = {3{BEQ }} & cmp_EQ  |
303	                      {3{BNE }} & cmp_NE  |
304	                      {3{BLT }} & cmp_LT  |
305	                      {3{BLTU}} & cmp_LTU |
306	                      {3{BGE }} & cmp_GE  |
307	                      {3{BGEU}} & cmp_GEU ;
308	
309	    // 实现：AUIPC/JAL/JALR 使用 PC 作为 ALU 的 A 操作数
310	    assign ALUSrc_A = AUIPC | JAL | JALR;
311	
312	    // 实现：立即数类/访存类指令使用立即数作为 ALU 的 B 操作数
313	    assign ALUSrc_B = I_valid | L_valid | S_valid | LUI | AUIPC;
314	
315	    // 实现：根据指令类型产生 ALUControl
316	    assign ALUControl = {4{ADD  | ADDI  | L_valid | S_valid | AUIPC}} & ALU_ADD  |
317	                        {4{SUB }}                                     & ALU_SUB  |
318	                        {4{AND  | ANDI }}                             & ALU_AND  |
319	                        {4{OR   | ORI  }}                             & ALU_OR   |
320	                        {4{XOR  | XORI }}                             & ALU_XOR  |
321	                        {4{SLL  | SLLI }}                             & ALU_SLL  |
322	                        {4{SRL  | SRLI }}                             & ALU_SRL  |
323	                        {4{SLT  | SLTI }}                             & ALU_SLT  |
324	                        {4{SLTU | SLTIU}}                             & ALU_SLTU |
325	                        {4{SRA  | SRAI }}                             & ALU_SRA  |
326	                        {4{JAL  | JALR }}                             & ALU_Ap4  |
327	                        {4{LUI }}                                     & ALU_Bout ;
328	
329	    // 实现：load 指令的写回数据来自存储器（同时也是 CMU 的读使能）
330	    assign DatatoReg = L_valid;
331	
332	    // 实现：写寄存器的指令集合
333	    assign RegWrite = R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR;
334	
335	    // 实现：store 指令写存储器（同时也是 CMU 的写使能）
336	    assign mem_w = S_valid;
337	
338	    // 实现：访存指令标志（load / store 都要访问存储器）
339	    assign MIO = L_valid | S_valid;
340	
341	    // 实现：使用 rs1 的指令
342	    assign rs1use = R_valid | I_valid | L_valid | S_valid | B_valid | JALR;
343	
344	    // 实现：使用 rs2 的指令
345	    assign rs2use = R_valid | S_valid | B_valid;
346	
347	    // 实现：hazard_optype —— load 为 2，store 为 3，其它写寄存器指令为 1，其余为 0
348	    assign hazard_optype = {2{L_valid}} & hazard_optype_LOAD  |
349	                           {2{S_valid}} & hazard_optype_STORE |
350	                           {2{R_valid | I_valid | LUI | AUIPC | JAL | JALR}} & hazard_optype_ALU ;
351	
352	endmodule

