  3	module ALU(
  4	    input[31:0] A, B,
  5	    input[3:0] Control,
  6	    output[31:0] res,
  7	    output zero, overflow
  8	);
  9	
 10	    parameter ALU_ADD  = 4'b0001;
 11	    parameter ALU_SUB  = 4'b0010;
 12	    parameter ALU_AND  = 4'b0011;
 13	    parameter ALU_OR   = 4'b0100;
 14	    parameter ALU_XOR  = 4'b0101;
 15	    parameter ALU_SLL  = 4'b0110;
 16	    parameter ALU_SRL  = 4'b0111;
 17	    parameter ALU_SLT  = 4'b1000;
 18	    parameter ALU_SLTU = 4'b1001;
 19	    parameter ALU_SRA  = 4'b1010;
 20	    parameter ALU_Ap4  = 4'b1011;
 21	    parameter ALU_Bout = 4'b1100;
 22	
 23	    wire[4:0] shamt = B[4:0];
 24	
 25	    // 实现：根据 Control 选择运算，并生成 zero / overflow 标志
 26	    wire[31:0] res_ADD  = A + B;
 27	    wire[31:0] res_SUB  = A - B;
 28	    wire[31:0] res_AND  = A & B;
 29	    wire[31:0] res_OR   = A | B;
 30	    wire[31:0] res_XOR  = A ^ B;
 31	    wire[31:0] res_SLL  = A << shamt;
 32	    wire[31:0] res_SRL  = A >> shamt;
 33	    wire[31:0] res_SRA  = $signed(A) >>> shamt;
 34	    wire       res_lt   = $signed(A) < $signed(B);
 35	    wire       res_ltu  = A < B;
 36	    wire[31:0] res_SLT  = {31'b0, res_lt};
 37	    wire[31:0] res_SLTU = {31'b0, res_ltu};
 38	    wire[31:0] res_Ap4  = A + 32'd4;
 39	    wire[31:0] res_Bout = B;
 40	
 41	    wire is_ADD  = Control == ALU_ADD ;
 42	    wire is_SUB  = Control == ALU_SUB ;
 43	    wire is_AND  = Control == ALU_AND ;
 44	    wire is_OR   = Control == ALU_OR  ;
 45	    wire is_XOR  = Control == ALU_XOR ;
 46	    wire is_SLL  = Control == ALU_SLL ;
 47	    wire is_SRL  = Control == ALU_SRL ;
 48	    wire is_SLT  = Control == ALU_SLT ;
 49	    wire is_SLTU = Control == ALU_SLTU;
 50	    wire is_SRA  = Control == ALU_SRA ;
 51	    wire is_Ap4  = Control == ALU_Ap4 ;
 52	    wire is_Bout = Control == ALU_Bout;
 53	
 54	    assign res = {32{is_ADD }} & res_ADD  |
 55	                 {32{is_SUB }} & res_SUB  |
 56	                 {32{is_AND }} & res_AND  |
 57	                 {32{is_OR  }} & res_OR   |
 58	                 {32{is_XOR }} & res_XOR  |
 59	                 {32{is_SLL }} & res_SLL  |
 60	                 {32{is_SRL }} & res_SRL  |
 61	                 {32{is_SLT }} & res_SLT  |
 62	                 {32{is_SLTU}} & res_SLTU |
 63	                 {32{is_SRA }} & res_SRA  |
 64	                 {32{is_Ap4 }} & res_Ap4  |
 65	                 {32{is_Bout}} & res_Bout ;
 66	
 67	    assign zero = ~(|res);
 68	
 69	    assign overflow = is_ADD & (~(A[31] ^ B[31]) & (res_ADD[31] ^ A[31])) |
 70	                      is_SUB & ( (A[31] ^ B[31]) & (res_SUB[31] ^ A[31])) ;
 71	
 72	endmodule`timescale 1ns / 1ps
