 93	module    REG_IF_ID(input clk,                                      //IF/ID Latch
 94	                    input rst,
 95	                    input EN,                                       //流水寄存器使能
 96	                    input Data_stall,                               //数据竞争等待
 97	                    input flush,                                    //控制竞争清除并等待
 98	                    input [31:0] PCOUT,                             //指令存储器指针
 99	                    input [31:0] IR,                                //指令存储器输出
100	
101	                    output reg[31:0] IR_ID,                         //取指锁存
102	                    output reg[31:0] PCurrent_ID                    //当前存在指令地址
103	                );
104	
105	//reg[31:0]PCurrent_ID,IR_ID;
106	    // 实现：IF/ID 流水寄存器
107	    // 复位：IR_ID 置为 NOP，PCurrent_ID 清零
108	    // EN 有效时：数据竞争(Data_stall)保持原值；控制竞争(flush)插入 NOP 气泡；
109	    //            否则正常锁存取指结果。EN 无效（cache 缺失）时整体冻结。
110	    always @(posedge clk) begin
111	        if (rst) begin
112	            IR_ID       <= 32'h00000013;    // NOP
113	            PCurrent_ID <= 32'h00000000;
114	        end
115	        else if (EN) begin
116	            if (Data_stall) begin           // 数据竞争：保持原值
117	                IR_ID       <= IR_ID;
118	                PCurrent_ID <= PCurrent_ID;
119	            end
120	            else if (flush) begin           // 控制竞争：插入气泡
121	                IR_ID       <= 32'h00000013;
122	                PCurrent_ID <= PCurrent_ID;
123	            end
124	            else begin
125	                IR_ID       <= IR;
126	                PCurrent_ID <= PCOUT;
127	            end
128	        end
129	    end
130	
131	endmodule`timescale 1ns / 1ps
