274	module   REG_EX_MEM(input clk,                                      //EX/MEM Latch
275	                    input rst,
276	                    input EN,                                       //流水寄存器使�?
277	                    input flush,                                    //异常时清除异常指令并等待中断处理(保留)�?
278	                    input [31:0] IR_EX,                             //当前执行指令(测试)
279	                    input [31:0] PCurrent_EX,                       //当前执行指令存储器指�?
280	                    input [31:0] ALUO_EX,                           //当前ALU执行输出：有效地�?或ALU操作
281	                    input [31:0] B_EX,                              //ID级读出寄存器B数据：CPU输出数据
282	                    input [4:0]  rd_EX,                             //传�?�当前指令写目的寄存器地�?
283	                    input DatatoReg_EX,                      //传�?�当前指令REG写数据�?�道选择
284	                    input RegWrite_EX,                              //传�?�当前指令寄存器写信�?
285	                    input WR_EX,                                    //传�?�当前指令存储器读写信号
286	                    input[2:0] u_b_h_w_EX,
287	                    input MIO_EX,
288	
289	                    output reg[31:0] PCurrent_MEM,                  //锁存传�?�当前指令地�?
290	                    output reg[31:0] IR_MEM,                        //锁存传�?�当前指�?(测试)
291	                    output reg[31:0] ALUO_MEM,                      //锁存ALU操作结果：有效地�?或ALU操作
292	                    output reg[31:0] Datao_MEM,                     //锁存传�?�当前指令输出MIO数据
